# Parse the schedule to compute total work minutes
import re

total_work_minutes = 0
for line in schedule_content.splitlines():
    line = line.strip()
    if line.startswith("Work hours"):
        # Extract duration and unit
        match = re.search(r'(\d+)\s*(minutes|hours)', line)
        if match:
            value = int(match.group(1))
            unit = match.group(2)
            if unit == 'hours':
                total_work_minutes += value * 60
            else:
                total_work_minutes += value
print("Total work minutes:", total_work_minutes)

